#!/bin/sh
# A stand-in for the PrusaSlicer command line, for the tests of this module.
#
# It reads what to do from the word after "mode:" in the project file it is
# given. A test stores that word uncompressed in the project, so it needs no
# environment variable, which the sandbox would not pass on:
#
#   binary   print progress and write a binary G-code file
#   text     write a text G-code file
#   nothing  print what PrusaSlicer prints for an empty bed, write nothing
#   fail     print an error and stop with status 1
#   hang     wait until it is stopped
#   empty    write an empty file
#   args     write its own arguments into the output, one per line
out=""
input=""
all="$*"
while [ $# -gt 0 ]; do
	case "$1" in
	--output) out="$2"; shift 2 ;;
	--datadir | --threads | --load) shift 2 ;;
	--help) echo "PrusaSlicer-2.9.6 based on Slic3r (with GUI support)"; exit 0 ;;
	--*) shift ;;
	*) input="$1"; shift ;;
	esac
done

mode=$(grep -a -o 'mode:[a-z]*' "$input" | head -n 1 | cut -d: -f2)

case "$mode" in
binary)
	echo "10 => Processing triangulated mesh"
	echo "90 => Exporting G-code to $out"
	printf 'GCDE\001\000\000\000\001\000' > "$out"
	echo "Slicing result exported to $out"
	;;
text)
	printf '; generated by PrusaSlicer 2.9.6\nG28\n' > "$out"
	;;
nothing)
	echo "All objects are outside of the print volume."
	;;
fail)
	echo "Loading of a model file failed." >&2
	exit 1
	;;
hang)
	sleep 60
	;;
empty)
	: > "$out"
	;;
args)
	printf '%s\n' "$all" > "$out"
	;;
esac
exit 0
